  ngOnInit(): void {

    this.siteKey = G.SiteKey;

    this.questionForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(80)]],
      description: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]]
    });

    this.questionAnswerForm = this.fb.group({
      answer: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]]
    });

    this.replyForm = this.fb.group({
      comment: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(2000)]]
    });

    this.subscriptions.add(GResponse.getCartCoursesCount().subscribe(count => this.cartCoursesCount = count));
    this.subscriptions.add(GResponse.getCartProductsCount().subscribe(count => this.cartProductsCount = count));
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }


